'use strict';

/**
 * Task-local packaging + validation for the slack-api skill.
 * Mirrors the skill-creator package step: validates frontmatter/naming/no-TODO,
 * then writes a .skill file (a ZIP) with entries rooted at the skill folder.
 */

const fs = require('fs');
const path = require('path');
const zlib = require('zlib');

const rootArg = process.argv[2] || 'slack-api';
const outArg = process.argv[3] || 'dist';
const rootDir = path.resolve(__dirname, rootArg);
const skillName = path.basename(rootDir);
const outDir = path.resolve(__dirname, outArg);

const DOS_TIME = (12 << 11) | (0 << 5) | 0; // 12:00:00
const DOS_DATE = ((2024 - 1980) << 9) | (1 << 5) | 1; // 2024-01-01

// ---------- validation ----------

function collectFiles(dir, prefix) {
  const out = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true }).sort((a, b) => (a.name < b.name ? -1 : 1))) {
    const abs = path.join(dir, entry.name);
    const name = prefix + entry.name;
    if (entry.isDirectory()) {
      out.push.apply(out, collectFiles(abs, name + '/'));
    } else if (entry.isFile()) {
      out.push({ abs, name });
    }
  }
  return out;
}

const allFiles = collectFiles(rootDir, skillName + '/');
if (!fs.existsSync(path.join(rootDir, 'SKILL.md'))) {
  console.error('Validation failed: missing SKILL.md in ' + rootDir);
  process.exit(1);
}
const skillMd = fs.readFileSync(path.join(rootDir, 'SKILL.md'), 'utf8');
const fm = /^---\r?\n([\s\S]*?)\r?\n---\r?\n/.exec(skillMd);
if (!fm) {
  console.error('Validation failed: SKILL.md has no YAML frontmatter.');
  process.exit(1);
}
const nameMatch = /^name:\s*(\S+)\s*$/m.exec(fm[1]);
const descMatch = /^description:\s*(.+)$/m.exec(fm[1]);
if (!nameMatch || nameMatch[1] !== skillName) {
  console.error('Validation failed: frontmatter name "' + (nameMatch && nameMatch[1]) + '" does not match folder "' + skillName + '".');
  process.exit(1);
}
if (!descMatch || descMatch[1].trim().length === 0 || descMatch[1].trim().split('\n').length > 1) {
  console.error('Validation failed: description must be a single non-empty line.');
  process.exit(1);
}
for (const f of allFiles) {
  const text = fs.readFileSync(f.abs, 'utf8');
  if (/TODO|example_/i.test(text) || /example_/.test(f.name)) {
    console.error('Validation failed: leftover placeholder in ' + f.name);
    process.exit(1);
  }
}
console.log('Validation passed: name=' + skillName + ', description=' + descMatch[1].trim().slice(0, 60) + '..., files=' + allFiles.length);

// ---------- minimal ZIP writer ----------

let CRC_TABLE = null;
function crc32(buf) {
  if (!CRC_TABLE) {
    CRC_TABLE = new Uint32Array(256);
    for (let n = 0; n < 256; n++) {
      let c = n;
      for (let k = 0; k < 8; k++) {
        c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
      }
      CRC_TABLE[n] = c >>> 0;
    }
  }
  let c = 0xffffffff;
  for (let i = 0; i < buf.length; i++) {
    c = CRC_TABLE[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
  }
  return (c ^ 0xffffffff) >>> 0;
}

function localHeader(name, crc, compSize, uncompSize) {
  const nameBuf = Buffer.from(name, 'utf8');
  const b = Buffer.alloc(30 + nameBuf.length);
  b.writeUInt32LE(0x04034b50, 0);
  b.writeUInt16LE(20, 4);
  b.writeUInt16LE(0, 6);
  b.writeUInt16LE(8, 8);
  b.writeUInt16LE(DOS_TIME, 10);
  b.writeUInt16LE(DOS_DATE, 12);
  b.writeUInt32LE(crc, 14);
  b.writeUInt32LE(compSize, 18);
  b.writeUInt32LE(uncompSize, 22);
  b.writeUInt16LE(nameBuf.length, 26);
  b.writeUInt16LE(0, 28);
  nameBuf.copy(b, 30);
  return b;
}

function centralHeader(name, crc, compSize, uncompSize, offset) {
  const nameBuf = Buffer.from(name, 'utf8');
  const b = Buffer.alloc(46 + nameBuf.length);
  b.writeUInt32LE(0x02014b50, 0);
  b.writeUInt16LE(0x0314, 4); // version made by (unix, 2.0)
  b.writeUInt16LE(20, 6);
  b.writeUInt16LE(0, 8);
  b.writeUInt16LE(8, 10);
  b.writeUInt16LE(DOS_TIME, 12);
  b.writeUInt16LE(DOS_DATE, 14);
  b.writeUInt32LE(crc, 16);
  b.writeUInt32LE(compSize, 20);
  b.writeUInt32LE(uncompSize, 24);
  b.writeUInt16LE(nameBuf.length, 28);
  b.writeUInt16LE(0, 30); // extra len
  b.writeUInt16LE(0, 32); // comment len
  b.writeUInt16LE(0, 34); // disk start
  b.writeUInt16LE(0, 36); // internal attrs
  b.writeUInt32LE(0o100644 << 16, 38); // external attrs
  b.writeUInt32LE(offset, 42);
  nameBuf.copy(b, 46);
  return b;
}

const parts = [];
const centrals = [];
let offset = 0;
for (const f of allFiles) {
  const data = fs.readFileSync(f.abs);
  const crc = crc32(data);
  const comp = zlib.deflateRawSync(data);
  parts.push(localHeader(f.name, crc, comp.length, data.length), comp);
  centrals.push(centralHeader(f.name, crc, comp.length, data.length, offset));
  offset += 30 + Buffer.byteLength(f.name) + comp.length;
}

const cdSize = centrals.reduce(function (sum, b) { return sum + b.length; }, 0);
const eocd = Buffer.alloc(22);
eocd.writeUInt32LE(0x06054b50, 0);
eocd.writeUInt16LE(0, 4);
eocd.writeUInt16LE(0, 6);
eocd.writeUInt16LE(allFiles.length, 8);
eocd.writeUInt16LE(allFiles.length, 10);
eocd.writeUInt32LE(cdSize, 12);
eocd.writeUInt32LE(offset, 16);
eocd.writeUInt16LE(0, 20);

const zipBuf = Buffer.concat(parts.concat(centrals, [eocd]));
fs.mkdirSync(outDir, { recursive: true });
const outFile = path.join(outDir, skillName + '.skill');
fs.writeFileSync(outFile, zipBuf);

// ---------- verification (parse the archive we wrote) ----------

const verify = fs.readFileSync(outFile);
const eocdAt = verify.length - 22;
if (verify.readUInt32LE(eocdAt) !== 0x06054b50) {
  console.error('Verification failed: bad end-of-central-directory.');
  process.exit(1);
}
const count = verify.readUInt16LE(eocdAt + 10);
const cdStart = verify.readUInt32LE(eocdAt + 16);
const names = [];
let p = cdStart;
for (let i = 0; i < count; i++) {
  if (verify.readUInt32LE(p) !== 0x02014b50) {
    console.error('Verification failed: bad central directory entry ' + i + '.');
    process.exit(1);
  }
  const nameLen = verify.readUInt16LE(p + 28);
  const extraLen = verify.readUInt16LE(p + 30);
  const commentLen = verify.readUInt16LE(p + 32);
  names.push(verify.slice(p + 46, p + 46 + nameLen).toString('utf8'));
  p += 46 + nameLen + extraLen + commentLen;
}
const expected = allFiles.map(function (f) { return f.name; }).sort();
if (JSON.stringify(names.sort()) !== JSON.stringify(expected)) {
  console.error('Verification failed: entry mismatch.');
  process.exit(1);
}
names.forEach(function (n) {
  console.log('Entry: ' + n);
});
console.log('Packaged ' + outFile + ' (' + names.length + ' entries, ' + zipBuf.length + ' bytes).');

