#!/usr/bin/env node
'use strict';

/**
 * Slack Web API helper.
 * Calls any Slack Web API method and prints the response JSON.
 *
 * Usage:
 *   node scripts/slack_request.cjs METHOD key=value ... [--token TOKEN] [--get] [--base-url URL] [--max-chars=N]
 */

const http = require('http');
const https = require('https');
const { URL, URLSearchParams } = require('url');

const DEFAULT_MAX_CHARS = 20000;
const MAX_RETRIES = 4; // total attempts when HTTP 429 keeps coming back

function usage() {
  process.stdout.write(
    [
      'Slack Web API helper',
      '',
      'Usage:',
      '  node scripts/slack_request.cjs METHOD key=value [key=value ...] [options]',
      '',
      'Examples:',
      '  node scripts/slack_request.cjs auth.test',
      '  node scripts/slack_request.cjs chat.postMessage channel=C123 text="Deploy finished"',
      '  node scripts/slack_request.cjs conversations.history channel=C123 limit=10 --get',
      '',
      'Options:',
      '  --token TOKEN     Token to use (default: $SLACK_BOT_TOKEN, then $SLACK_USER_TOKEN)',
      '  --base-url URL    API base URL (default: https://slack.com/api)',
      '  --get             Send an HTTP GET request (read-only methods only)',
      '  --max-chars=N     Truncate stdout JSON after N chars (default 20000)',
      '  --help, -h        Show this help',
      '',
      'Structured values (blocks, files, ...) are JSON and are sent as-is.',
      'Success prints response JSON to stdout (exit 0). API errors exit 1 with the',
      'Slack error code on stderr. HTTP 429 is retried automatically.',
      ''
    ].join('\n')
  );
}

function fail(msg, code) {
  process.stderr.write('Error: ' + msg + '\n');
  process.exit(code);
}

function sleep(ms) {
  return new Promise(function (resolve) {
    setTimeout(resolve, ms);
  });
}

function doRequest(base, methodName, params, useGet, token) {
  return new Promise(function (resolve, reject) {
    let u;
    try {
      u = new URL(base);
    } catch (e) {
      reject(new Error('Invalid --base-url: ' + base));
      return;
    }
    const mod = u.protocol === 'https:' ? https : http;
    const basePath = (u.pathname || '/').replace(/\/+$/, '');
    const qs = useGet ? '?' + params.toString() : '';
    const path = basePath + '/' + methodName + qs;
    const headers = { Authorization: 'Bearer ' + token, Accept: 'application/json' };
    let body = null;
    let method = useGet ? 'GET' : 'POST';
    if (!useGet) {
      body = params.toString();
      headers['Content-Type'] = 'application/x-www-form-urlencoded';
      headers['Content-Length'] = Buffer.byteLength(body);
    }
    const req = mod.request(
      {
        hostname: u.hostname,
        port: u.port ? Number(u.port) : u.protocol === 'https:' ? 443 : 80,
        method: method,
        path: path,
        headers: headers
      },
      function (res) {
        const chunks = [];
        res.on('data', function (c) {
          chunks.push(c);
        });
        res.on('end', function () {
          resolve({
            status: res.statusCode,
            headers: res.headers,
            body: Buffer.concat(chunks).toString('utf8')
          });
        });
      }
    );
    req.on('error', reject);
    req.setTimeout(60000, function () {
      req.destroy(new Error('Request timed out after 60s'));
    });
    if (body) {
      req.write(body);
    }
    req.end();
  });
}

function writeStdout(text, maxChars) {
  if (text.length <= maxChars) {
    process.stdout.write(text + '\n');
    return;
  }
  process.stdout.write(text.slice(0, maxChars) + '\n');
  process.stderr.write(
    'Response truncated: omitted ' + (text.length - maxChars) + ' chars (raise with --max-chars=N).\n'
  );
}

async function main() {
  const argv = process.argv.slice(2);
  if (argv.length === 0 || argv.indexOf('--help') !== -1 || argv.indexOf('-h') !== -1) {
    usage();
    return;
  }

  let token = process.env.SLACK_BOT_TOKEN || process.env.SLACK_USER_TOKEN || '';
  let base = 'https://slack.com/api';
  let useGet = false;
  let maxChars = DEFAULT_MAX_CHARS;
  let method = '';
  const params = new URLSearchParams();

  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--token') {
      token = argv[++i] || '';
    } else if (a === '--base-url') {
      base = argv[++i] || '';
    } else if (a === '--get') {
      useGet = true;
    } else if (a.indexOf('--max-chars=') === 0) {
      const n = parseInt(a.slice('--max-chars='.length), 10);
      maxChars = Number.isFinite(n) && n > 0 ? n : DEFAULT_MAX_CHARS;
    } else if (a.charAt(0) === '-' && a.length > 1 && a !== '-' && a !== '--') {
      fail('Unknown option: ' + a + ' (try --help)', 2);
      return;
    } else if (!method) {
      method = a;
    } else {
      const eq = a.indexOf('=');
      if (eq <= 0) {
        fail('Invalid parameter (expected key=value): ' + a, 2);
        return;
      }
      const key = a.slice(0, eq);
      const value = a.slice(eq + 1);
      if (!/^[A-Za-z0-9_]+$/.test(key)) {
        fail('Invalid parameter name: ' + key, 2);
        return;
      }
      params.append(key, value);
    }
  }

  if (!method) {
    fail('Missing METHOD argument (try --help).', 2);
    return;
  }
  if (!/^[A-Za-z][A-Za-z0-9_.]{0,63}$/.test(method)) {
    fail('Invalid method name: ' + method, 2);
    return;
  }
  if (!token) {
    fail('No Slack token: set SLACK_BOT_TOKEN or SLACK_USER_TOKEN, or pass --token TOKEN.', 2);
    return;
  }

  let last = null;
  for (let attempt = 1; attempt <= MAX_RETRIES; attempt++) {
    const res = await doRequest(base, method, params, useGet, token);
    if (res.status === 429 && attempt < MAX_RETRIES) {
      const retryAfter = parseFloat(res.headers['retry-after']);
      const waitMs =
        Number.isFinite(retryAfter) && retryAfter >= 0 ? retryAfter * 1000 : 1000 * attempt;
      process.stderr.write(
        'Rate limited (HTTP 429); retrying in ' + waitMs / 1000 + 's (attempt ' + attempt + ' of ' + MAX_RETRIES + ').\n'
      );
      await sleep(waitMs);
      continue;
    }
    last = res;
    break;
  }

  const out = (last.body || '').trim();
  let parsed = null;
  try {
    parsed = JSON.parse(out);
  } catch (e) {
    parsed = null;
  }

  if (parsed) {
    const pretty = JSON.stringify(parsed, null, 2);
    if (parsed.ok === false) {
      let msg = 'Slack API error: ' + String(parsed.error || 'unknown');
      if (parsed.needed) {
        msg += ' (needs scope: ' + parsed.needed + ')';
      }
      if (parsed.provided) {
        msg += ' (token provides: ' + parsed.provided + ')';
      }
      process.stderr.write(msg + '\n');
      writeStdout(pretty, maxChars);
      process.exitCode = 1;
      return;
    }
    writeStdout(pretty, maxChars);
    return;
  }

  process.stderr.write('HTTP ' + last.status + ' returned a non-JSON body.\n');
  writeStdout(out, maxChars);
  process.exitCode = last.status >= 400 ? 3 : 0;
}

main().catch(function (err) {
  process.stderr.write('Network error: ' + (err && err.message ? err.message : String(err)) + '\n');
  process.exitCode = 2;
});

'use strict';

/**
 * Smoke test for slack-api/scripts/slack_request.cjs.
 * Starts a local HTTP server that imitates the Slack Web API, drives the real
 * helper CLI against it, and asserts request construction and output handling.
 */

const assert = require('assert');
const http = require('http');
const { execFile } = require('child_process');
const path = require('path');

const HELPER = path.join(__dirname, 'slack-api', 'scripts', 'slack_request.cjs');

function runHelper(args) {
  return new Promise(function (resolve) {
    execFile(
      process.execPath,
      [HELPER].concat(args),
      { timeout: 30000 },
      function (err, stdout, stderr) {
        resolve({ code: err && typeof err.code === 'number' ? err.code : err ? -1 : 0, stdout: stdout, stderr: stderr });
      }
    );
  });
}

function makeServer() {
  const state = {
    hits: { post: 0, get: 0, error: 0, retry: 0 },
    last: null
  };
  const server = http.createServer(function (req, res) {
    const chunks = [];
    req.on('data', function (c) {
      chunks.push(c);
    });
    req.on('end', function () {
      const u = new URL(req.url, 'http://localhost');
      const bodyText = Buffer.concat(chunks).toString('utf8');
      state.last = {
        method: req.method,
        path: u.pathname,
        headers: req.headers,
        query: u.searchParams,
        body: bodyText,
        form: new URLSearchParams(bodyText)
      };
      const json = function (status, obj, extraHeaders) {
        const headers = Object.assign({ 'content-type': 'application/json' }, extraHeaders || {});
        res.writeHead(status, headers);
        res.end(JSON.stringify(obj));
      };
      switch (u.pathname) {
        case '/api/chat.postMessage':
          state.hits.post += 1;
          json(200, { ok: true, channel: 'C123', ts: '1719000000.000100' });
          break;
        case '/api/conversations.history':
          state.hits.get += 1;
          json(200, {
            ok: true,
            messages: [{ type: 'message', user: 'U1', text: 'hi', ts: '1719000000.000001' }],
            response_metadata: { next_cursor: '' }
          });
          break;
        case '/api/auth.test':
          state.hits.error += 1;
          json(200, {
            ok: false,
            error: 'invalid_auth',
            needed: 'chat:write',
            provided: 'channels:read'
          });
          break;
        case '/api/chat.delete':
          state.hits.retry += 1;
          if (state.hits.retry <= 2) {
            res.writeHead(429, { 'content-type': 'application/json', 'retry-after': '0' });
            res.end(JSON.stringify({ ok: false, error: 'too_many_requests' }));
          } else {
            json(200, { ok: true, channel: 'C123', ts: '1719000000.000200' });
          }
          break;
        default:
          json(500, { ok: false, error: 'test_unhandled_path' });
      }
    });
  });
  return new Promise(function (resolve) {
    server.listen(0, '127.0.0.1', function () {
      resolve({ server: server, state: state, base: 'http://127.0.0.1:' + server.address().port });
    });
  });
}

const BLOCKS_JSON = '[{"type":"section","text":{"type":"mrkdwn","text":"hi"}}]';

async function run() {
  const { server, state, base } = await makeServer();
  const results = [];
  const scenario = async function (name, fn) {
    try {
      await fn();
      results.push('PASS ' + name);
    } catch (e) {
      results.push('FAIL ' + name + ': ' + (e && e.message ? e.message : e));
    }
  };

  await scenario('POST with form params and JSON pass-through', async function () {
    const r = await runHelper([
      'chat.postMessage',
      'channel=C123',
      'text=hello world',
      'link_names=1',
      'blocks=' + BLOCKS_JSON,
      '--token',
      'xoxb-test-1',
      '--base-url',
      base
    ]);
    assert.strictEqual(r.code, 0, 'exit code: ' + r.code + ' stderr: ' + r.stderr);
    assert.strictEqual(state.last.method, 'POST');
    assert.strictEqual(state.last.path, '/api/chat.postMessage');
    assert.strictEqual(state.last.headers.authorization, 'Bearer xoxb-test-1');
    assert.ok(
      String(state.last.headers['content-type']).indexOf('application/x-www-form-urlencoded') === 0,
      'content-type is form-encoded'
    );
    assert.strictEqual(state.last.form.get('channel'), 'C123');
    assert.strictEqual(state.last.form.get('text'), 'hello world');
    assert.strictEqual(state.last.form.get('link_names'), '1');
    assert.strictEqual(state.last.form.get('blocks'), BLOCKS_JSON);
    const out = JSON.parse(r.stdout);
    assert.strictEqual(out.ok, true);
    assert.strictEqual(out.ts, '1719000000.000100');
  });

  await scenario('GET request for read-only method', async function () {
    const r = await runHelper([
      'conversations.history',
      'channel=C123',
      'limit=5',
      '--get',
      '--token',
      'xoxb-test-1',
      '--base-url',
      base
    ]);
    assert.strictEqual(r.code, 0, 'exit code: ' + r.code + ' stderr: ' + r.stderr);
    assert.strictEqual(state.last.method, 'GET');
    assert.strictEqual(state.last.path, '/api/conversations.history?channel=C123&limit=5');
    const out = JSON.parse(r.stdout);
    assert.strictEqual(out.ok, true);
    assert.strictEqual(out.messages.length, 1);
  });

  await scenario('API error handling (ok:false, exit 1, diagnostic on stderr)', async function () {
    const r = await runHelper(['auth.test', '--token', 'xoxb-test-1', '--base-url', base]);
    assert.strictEqual(r.code, 1, 'exit code: ' + r.code);
    assert.ok(r.stderr.indexOf('invalid_auth') !== -1, 'stderr has error code: ' + r.stderr);
    assert.ok(r.stderr.indexOf('chat:write') !== -1, 'stderr has needed scope: ' + r.stderr);
    const out = JSON.parse(r.stdout);
    assert.strictEqual(out.ok, false);
  });

  await scenario('HTTP 429 retry then success', async function () {
    const r = await runHelper(['chat.delete', 'channel=C123', 'ts=123', '--token', 'xoxb-test-1', '--base-url', base]);
    assert.strictEqual(r.code, 0, 'exit code: ' + r.code + ' stderr: ' + r.stderr);
    assert.strictEqual(state.hits.retry, 3, 'two 429 responses then success');
    assert.ok(r.stderr.indexOf('Rate limited') !== -1, 'stderr mentions retry: ' + r.stderr);
  });

  await scenario('Missing token fails cleanly (exit 2)', async function () {
    delete process.env.SLACK_BOT_TOKEN;
    delete process.env.SLACK_USER_TOKEN;
    const r = await runHelper(['auth.test', '--base-url', base]);
    assert.strictEqual(r.code, 2, 'exit code: ' + r.code);
    assert.ok(r.stderr.indexOf('SLACK_BOT_TOKEN') !== -1, 'stderr mentions token env var: ' + r.stderr);
  });

  server.close();
  process.stdout.write(results.join('\n') + '\n');
  process.exit(results.some(function (x) { return x.indexOf('FAIL') === 0; }) ? 1 : 0);
}

run().catch(function (e) {
  process.stderr.write('Test harness error: ' + (e && e.stack ? e.stack : e) + '\n');
  process.exit(1);
});

'use strict';

/**
 * Task-local packaging + validation for the slack-api skill.
 * Mirrors the skill-creator package step: validates frontmatter/naming/no-TODO,
 * then writes a .skill file (a ZIP) with entries rooted at the skill folder.
 */

const fs = require('fs');
const path = require('path');
const zlib = require('zlib');

const rootArg = process.argv[2] || 'slack-api';
const outArg = process.argv[3] || 'dist';
const rootDir = path.resolve(__dirname, rootArg);
const skillName = path.basename(rootDir);
const outDir = path.resolve(__dirname, outArg);

const DOS_TIME = (12 << 11) | (0 << 5) | 0; // 12:00:00
const DOS_DATE = ((2024 - 1980) << 9) | (1 << 5) | 1; // 2024-01-01

// ---------- validation ----------

function collectFiles(dir, prefix) {
  const out = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true }).sort((a, b) => (a.name < b.name ? -1 : 1))) {
    const abs = path.join(dir, entry.name);
    const name = prefix + entry.name;
    if (entry.isDirectory()) {
      out.push.apply(out, collectFiles(abs, name + '/'));
    } else if (entry.isFile()) {
      out.push({ abs, name });
    }
  }
  return out;
}

const allFiles = collectFiles(rootDir, skillName + '/');
if (!fs.existsSync(path.join(rootDir, 'SKILL.md'))) {
  console.error('Validation failed: missing SKILL.md in ' + rootDir);
  process.exit(1);
