#!/usr/bin/env node
'use strict';

/**
 * Slack Web API helper.
 * Calls any Slack Web API method and prints the response JSON.
 *
 * Usage:
 *   node scripts/slack_request.cjs METHOD key=value ... [--token TOKEN] [--get] [--base-url URL] [--max-chars=N]
 */

const http = require('http');
const https = require('https');
const { URL, URLSearchParams } = require('url');

const DEFAULT_MAX_CHARS = 20000;
const MAX_RETRIES = 4; // total attempts when HTTP 429 keeps coming back

function usage() {
  process.stdout.write(
    [
      'Slack Web API helper',
      '',
      'Usage:',
      '  node scripts/slack_request.cjs METHOD key=value [key=value ...] [options]',
      '',
      'Examples:',
      '  node scripts/slack_request.cjs auth.test',
      '  node scripts/slack_request.cjs chat.postMessage channel=C123 text="Deploy finished"',
      '  node scripts/slack_request.cjs conversations.history channel=C123 limit=10 --get',
      '',
      'Options:',
      '  --token TOKEN     Token to use (default: $SLACK_BOT_TOKEN, then $SLACK_USER_TOKEN)',
      '  --base-url URL    API base URL (default: https://slack.com/api)',
      '  --get             Send an HTTP GET request (read-only methods only)',
      '  --max-chars=N     Truncate stdout JSON after N chars (default 20000)',
      '  --help, -h        Show this help',
      '',
      'Structured values (blocks, files, ...) are JSON and are sent as-is.',
      'Success prints response JSON to stdout (exit 0). API errors exit 1 with the',
      'Slack error code on stderr. HTTP 429 is retried automatically.',
      ''
    ].join('\n')
  );
}

function fail(msg, code) {
  process.stderr.write('Error: ' + msg + '\n');
  process.exit(code);
}

function sleep(ms) {
  return new Promise(function (resolve) {
    setTimeout(resolve, ms);
  });
}

function doRequest(base, methodName, params, useGet, token) {
  return new Promise(function (resolve, reject) {
    let u;
    try {
      u = new URL(base);
    } catch (e) {
      reject(new Error('Invalid --base-url: ' + base));
      return;
    }
    const mod = u.protocol === 'https:' ? https : http;
    const basePath = (u.pathname || '/').replace(/\/+$/, '');
    const qs = useGet ? '?' + params.toString() : '';
    const path = basePath + '/' + methodName + qs;
    const headers = { Authorization: 'Bearer ' + token, Accept: 'application/json' };
    let body = null;
    let method = useGet ? 'GET' : 'POST';
    if (!useGet) {
      body = params.toString();
      headers['Content-Type'] = 'application/x-www-form-urlencoded';
      headers['Content-Length'] = Buffer.byteLength(body);
    }
    const req = mod.request(
      {
        hostname: u.hostname,
        port: u.port ? Number(u.port) : u.protocol === 'https:' ? 443 : 80,
        method: method,
        path: path,
        headers: headers
      },
      function (res) {
        const chunks = [];
        res.on('data', function (c) {
          chunks.push(c);
        });
        res.on('end', function () {
          resolve({
            status: res.statusCode,
            headers: res.headers,
            body: Buffer.concat(chunks).toString('utf8')
          });
        });
      }
    );
    req.on('error', reject);
    req.setTimeout(60000, function () {
      req.destroy(new Error('Request timed out after 60s'));
    });
    if (body) {
      req.write(body);
    }
    req.end();
  });
}

function writeStdout(text, maxChars) {
  if (text.length <= maxChars) {
    process.stdout.write(text + '\n');
    return;
  }
  process.stdout.write(text.slice(0, maxChars) + '\n');
  process.stderr.write(
    'Response truncated: omitted ' + (text.length - maxChars) + ' chars (raise with --max-chars=N).\n'
  );
}

async function main() {
  const argv = process.argv.slice(2);
  if (argv.length === 0 || argv.indexOf('--help') !== -1 || argv.indexOf('-h') !== -1) {
    usage();
    return;
  }

  let token = process.env.SLACK_BOT_TOKEN || process.env.SLACK_USER_TOKEN || '';
  let base = 'https://slack.com/api';
  let useGet = false;
  let maxChars = DEFAULT_MAX_CHARS;
  let method = '';
  const params = new URLSearchParams();

  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--token') {
      token = argv[++i] || '';
    } else if (a === '--base-url') {
      base = argv[++i] || '';
    } else if (a === '--get') {
      useGet = true;
    } else if (a.indexOf('--max-chars=') === 0) {
      const n = parseInt(a.slice('--max-chars='.length), 10);
      maxChars = Number.isFinite(n) && n > 0 ? n : DEFAULT_MAX_CHARS;
    } else if (a.charAt(0) === '-' && a.length > 1 && a !== '-' && a !== '--') {
      fail('Unknown option: ' + a + ' (try --help)', 2);
      return;
    } else if (!method) {
      method = a;
    } else {
      const eq = a.indexOf('=');
      if (eq <= 0) {
        fail('Invalid parameter (expected key=value): ' + a, 2);
        return;
      }
      const key = a.slice(0, eq);
      const value = a.slice(eq + 1);
      if (!/^[A-Za-z0-9_]+$/.test(key)) {
        fail('Invalid parameter name: ' + key, 2);
        return;
      }
      params.append(key, value);
    }
  }

  if (!method) {
    fail('Missing METHOD argument (try --help).', 2);
    return;
  }
  if (!/^[A-Za-z][A-Za-z0-9_.]{0,63}$/.test(method)) {
    fail('Invalid method name: ' + method, 2);
    return;
  }
  if (!token) {
    fail('No Slack token: set SLACK_BOT_TOKEN or SLACK_USER_TOKEN, or pass --token TOKEN.', 2);
    return;
  }

  let last = null;
  for (let attempt = 1; attempt <= MAX_RETRIES; attempt++) {
    const res = await doRequest(base, method, params, useGet, token);
    if (res.status === 429 && attempt < MAX_RETRIES) {
      const retryAfter = parseFloat(res.headers['retry-after']);
      const waitMs =
        Number.isFinite(retryAfter) && retryAfter >= 0 ? retryAfter * 1000 : 1000 * attempt;
      process.stderr.write(
        'Rate limited (HTTP 429); retrying in ' + waitMs / 1000 + 's (attempt ' + attempt + ' of ' + MAX_RETRIES + ').\n'
      );
      await sleep(waitMs);
      continue;
    }
    last = res;
    break;
  }

  const out = (last.body || '').trim();
  let parsed = null;
  try {
    parsed = JSON.parse(out);
  } catch (e) {
    parsed = null;
  }

  if (parsed) {
    const pretty = JSON.stringify(parsed, null, 2);
    if (parsed.ok === false) {
      let msg = 'Slack API error: ' + String(parsed.error || 'unknown');
      if (parsed.needed) {
        msg += ' (needs scope: ' + parsed.needed + ')';
      }
      if (parsed.provided) {
        msg += ' (token provides: ' + parsed.provided + ')';
      }
      process.stderr.write(msg + '\n');
      writeStdout(pretty, maxChars);
      process.exitCode = 1;
      return;
    }
    writeStdout(pretty, maxChars);
    return;
  }

  process.stderr.write('HTTP ' + last.status + ' returned a non-JSON body.\n');
  writeStdout(out, maxChars);
  process.exitCode = last.status >= 400 ? 3 : 0;
}

main().catch(function (err) {
  process.stderr.write('Network error: ' + (err && err.message ? err.message : String(err)) + '\n');
  process.exitCode = 2;
});

